
'use strict';
const $=id=>document.getElementById(id);
const store={
  get(k,d){try{const v=localStorage.getItem('dumda:'+k);return v?JSON.parse(v):d;}catch(e){return d;}},
  set(k,v){try{localStorage.setItem('dumda:'+k,JSON.stringify(v));}catch(e){}}
};
function go(id){
  document.querySelectorAll('section').forEach(s=>s.classList.toggle('on',s.id===id));
  document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.s===id));
  if(typeof window.scrollTo === 'function') window.scrollTo(0,0);
  if(id === 'handbook') renderHandbook();
  if(id === 'bahr') renderFams();
  if(id === 'exercises') renderExercises();
  if(id === 'dictionary') renderDictionary();
  if(id === 'studio') {
    if(!$('studioInput').value) {
      $('studioInput').value = "دلِ ناداں تجھے ہوا کیا ہے\nآخر اس درد کی دوا کیا ہے";
      runStudioScan();
    }
  }
}

