function normVerseKey(str) {
  if(!str) return '';
  return str.toLowerCase()
    .replace(/[\u064B-\u065F\u0670\u0640\u200C\u200D]/g, '')
    .replace(/[،۔؟!,.;:?"'«»()\[\]\-–—/]/g, '')
    .replace(/[آأإٱ]/g, 'ا')
    .replace(/[يى]/g, 'ی')
    .replace(/ك/g, 'ک')
    .replace(/[هۀۂە]/g, 'ہ')
    .replace(/[āá]/g, 'aa')
    .replace(/[īí]/g, 'ii')
    .replace(/[ūú]/g, 'uu')
    .replace(/[ñṅ]/g, 'n')
    .replace(/[ṭ]/g, 't')
    .replace(/[ḍ]/g, 'd')
    .replace(/[ṛ]/g, 'r')
    .replace(/[ṣ]/g, 's')
    .replace(/[żẕž]/g, 'z')
    .replace(/[z̤]/g, 'z')
    .replace(/[t̤]/g, 't')
    .replace(/[ḥ]/g, 'h')
    .replace(/[ʿʽ‘']/g, '')
    .replace(/[ʾ’]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/* Universal indexed dictionary of all classical verses across all 4 scripts */
const KNOWN_VERSES = {};
function registerKnownVerse(obj) {
  if(!obj) return;
  const entry = {
    ur: obj.ur || '',
    hi: obj.hi || '',
    ro: obj.ro || '',
    ascii: obj.ascii || ''
  };
  ['ur', 'hi', 'ro', 'ascii'].forEach(k => {
    if(obj[k]) {
      const nk = normVerseKey(obj[k]);
      if(nk) KNOWN_VERSES[nk] = entry;
    }
  });
}

// Index all exercises lines (226 lines across 24 ghazals)
EXERCISES_DATA.forEach(ex => {
  if(ex.lines) ex.lines.forEach(l => registerKnownVerse(l));
});

// Index all family famous verses (25 verses across 12 families)
if(typeof FAMS !== 'undefined') {
  FAMS.forEach(f => {
    if(f.gz) {
      f.gz.forEach(g => {
        registerKnownVerse({ ur: g.ur, hi: g.hi, ro: g.ro, ascii: g.ascii });
        if(g.ascii2) registerKnownVerse({ ur: g.ur2, hi: g.hi2, ro: g.ro2, ascii: g.ascii2 });
      });
    }
  });
}

/* Transliteration helpers for novel/arbitrary inputs */
function devToAscii(str) {
  if(!str) return '';
  const nuktaMap = { 'क़':'q','ख़':';x','ग़':';g','ज़':'z','ड़':';r','ढ़':';rh','फ़':'f' };
  const consMap = {
    'क':'k','ख':'kh','ग':'g','घ':'gh','ङ':'n',
    'च':'ch','छ':'chh','ज':'j','झ':'jh','ञ':'n',
    'ट':';t','ठ':';th','ड':';d','ढ':';dh','ण':'n',
    'त':'t','थ':'th','द':'d','ध':'dh','न':'n',
    'प':'p','फ':'ph','ब':'b','भ':'bh','म':'m',
    'य':'y','र':'r','ल':'l','व':'v',
    'श':'sh','ष':'sh','स':'s','ह':'h'
  };
  const vowelMap = { 'अ':'a','आ':'aa','इ':'i','ई':'ii','उ':'u','ऊ':'uu','ए':'e','ऐ':'ai','ओ':'o','औ':'au' };
  const matraMap = { 'ा':'aa','ि':'i','ी':'ii','ु':'u','ू':'uu','े':'e','ै':'ai','ो':'o','ौ':'au' };
  let s = str;
  for(const [k, v] of Object.entries(nuktaMap)) s = s.split(k).join(v);
  let out = '';
  for(let i = 0; i < s.length; i++) {
    const ch = s[i];
    const nextCh = s[i + 1] || '';
    if(consMap[ch]) {
      const c = consMap[ch];
      if(nextCh === '्') { out += c; i++; }
      else if(matraMap[nextCh]) { out += c + matraMap[nextCh]; i++; }
      else { out += c; }
    } else if(vowelMap[ch]) {
      out += vowelMap[ch];
    } else if(ch === 'ं' || ch === 'ँ') {
      out += ';n';
    } else if(ch === 'ः') {
      out += 'h';
    } else {
      out += ch;
    }
  }
  return out;
}

function romanToAscii(str) {
  if(!str) return '';
  let s = str.toLowerCase();
  s = s.replace(/ā/g, 'aa')
       .replace(/ī/g, 'ii')
       .replace(/ū/g, 'uu')
       .replace(/ñ/g, ';n')
       .replace(/ġh|ġ/g, ';g')
       .replace(/ḳh|ḳ/g, ';x')
       .replace(/ṭ/g, ';t')
       .replace(/ḍ/g, ';d')
       .replace(/ṛ/g, ';r')
       .replace(/ṣ/g, '.s')
       .replace(/ż|ẕ/g, ';z')
       .replace(/z̤/g, ':z')
       .replace(/t̤/g, ':t')
       .replace(/ḥ/g, ';h')
       .replace(/ʿ/g, '((')
       .replace(/[’ʾ']/g, '))')
       .replace(/u([aā])/g, 'u))$1');
  return s;
}

function urduToDevanagari(str) {
  if(!str) return '';
  const multiMap = [
    [/بھ/g, 'भ'], [/پھ/g, 'फ'], [/تھ/g, 'थ'], [/ٹھ/g, 'ठ'], [/جھ/g, 'झ'], [/چھ/g, 'छ'],
    [/دھ/g, 'ध'], [/ڈھ/g, 'ढ'], [/کھ/g, 'ख'], [/گھ/g, 'घ'], [/ڑھ/g, 'ढ़'],
    [/کیا/g, 'क्या'], [/کیوں/g, 'क्यों'], [/ہے/g, 'है'], [/ہیں/g, 'हैं'], [/تھے/g, 'थे'],
    [/تھی/g, 'थी'], [/تھا/g, 'था'], [/مجھ/g, 'मुझ'], [/تجھ/g, 'तुझ'], [/کچھ/g, 'कुछ'],
    [/دلِ/g, 'दिल-ए'], [/ہوا/g, 'हुआ'], [/دوا/g, 'दवा'], [/ناداں/g, 'नादाँ'], [/تجھے/g, 'तुझे']
  ];
  let s = str;
  multiMap.forEach(([re, rep]) => { s = s.replace(re, rep); });
  const singleMap = {
    'آ': 'आ', 'ا': 'ा', 'ب': 'ब', 'پ': 'प', 'ت': 'त', 'ٹ': 'ट', 'ث': 'स',
    'ج': 'ज', 'چ': 'च', 'ح': 'ह', 'خ': 'ख़', 'د': 'द', 'ڈ': 'ड', 'ذ': 'ज़',
    'ر': 'र', 'ڑ': 'ड़', 'ز': 'ज़', 'ژ': 'झ़', 'س': 'स', 'ش': 'श', 'ص': 'स',
    'ض': 'ज़', 'ط': 'त', 'ظ': 'ज़', 'ع': '', 'غ': 'ग़', 'ف': 'फ़', 'ق': 'क़',
    'ک': 'क', 'گ': 'ग', 'ل': 'ल', 'م': 'म', 'ن': 'न', 'ں': 'ँ', 'و': 'ो',
    'ہ': 'ह', 'ۂ': 'ह-ए', 'ھ': 'ह', 'ء': '', 'ی': 'ी', 'ے': 'े', 'ۓ': 'ए',
    'ِ': '-ए-', 'ُ': 'ु', 'َ': ''
  };
  let out = '';
  for(let i = 0; i < s.length; i++) {
    const ch = s[i];
    if(singleMap[ch] !== undefined) {
      if(ch === 'ا' && (i === 0 || /\s/.test(s[i - 1]))) out += 'अ';
      else out += singleMap[ch];
    } else {
      out += ch;
    }
  }
  return out;
}

function urduToRoman(str) {
  if(!str) return '';
  const multiMap = [
    [/بھ/g, 'bh'], [/پھ/g, 'ph'], [/تھ/g, 'th'], [/ٹھ/g, 'ṭh'], [/جھ/g, 'jh'], [/چھ/g, 'chh'],
    [/دھ/g, 'dh'], [/ڈھ/g, 'ḍh'], [/کھ/g, 'kh'], [/گھ/g, 'gh'], [/ڑھ/g, 'ṛh'],
    [/کیا/g, 'kyā'], [/کیوں/g, 'kyūñ'], [/ہے/g, 'hai'], [/ہیں/g, 'haiñ'], [/تھے/g, 'the'],
    [/تھی/g, 'thī'], [/تھا/g, 'thā'], [/مجھ/g, 'mujh'], [/تجھ/g, 'tujh'], [/کچھ/g, 'kuchh'],
    [/دلِ/g, 'dil-e'], [/ہوا/g, 'huʾā'], [/دوا/g, 'davā'], [/ناداں/g, 'nādāñ'], [/تجھے/g, 'tujhe']
  ];
  let s = str;
  multiMap.forEach(([re, rep]) => { s = s.replace(re, rep); });
  const singleMap = {
    'آ': 'ā', 'ا': 'ā', 'ب': 'b', 'پ': 'p', 'ت': 't', 'ٹ': 'ṭ', 'ث': 's̱',
    'ج': 'j', 'چ': 'ch', 'ح': 'ḥ', 'خ': 'ḳh', 'د': 'd', 'ڈ': 'ḍ', 'ذ': 'ẕ',
    'ر': 'r', 'ڑ': 'ṛ', 'ز': 'z', 'ژ': 'zh', 'س': 's', 'ش': 'sh', 'ص': 'ṣ',
    'ض': 'ż', 'ط': 't̤', 'ظ': 'z̤', 'ع': 'ʿ', 'غ': 'ġh', 'ف': 'f', 'ق': 'q',
    'ک': 'k', 'گ': 'g', 'ل': 'l', 'م': 'm', 'ن': 'n', 'ں': 'ñ', 'و': 'o',
    'ہ': 'h', 'ۂ': 'h-e', 'ھ': 'h', 'ء': '’', 'ی': 'ī', 'ے': 'e', 'ۓ': '’e',
    'ِ': '-e', 'ُ': 'u', 'َ': 'a'
  };
  let out = '';
  for(let i = 0; i < s.length; i++) {
    const ch = s[i];
    if(singleMap[ch] !== undefined) {
      if(ch === 'ا' && (i === 0 || /\s/.test(s[i - 1]))) out += 'a';
      else out += singleMap[ch];
    } else {
      out += ch;
    }
  }
  return out;
}

function getLineDisplay(lineObj, script) {
  if(!lineObj) return '';
  if(typeof lineObj === 'string') {
    const nk = normVerseKey(lineObj);
    if(KNOWN_VERSES[nk]) return getLineDisplay(KNOWN_VERSES[nk], script);
    if(script === 'ur') return lineObj;
    if(script === 'hi') return urduToDevanagari(lineObj);
    if(script === 'ro') return urduToRoman(lineObj);
    return lineObj;
  }
  if(script === 'ascii') return lineObj.ascii || lineObj.ro || lineObj.ur || '';
  if(script === 'hi') return lineObj.hi || urduToDevanagari(lineObj.ur) || lineObj.ascii || '';
  if(script === 'ro') return lineObj.ro || urduToRoman(lineObj.ur) || lineObj.ascii || '';
  return lineObj.ur || lineObj.ascii || '';
}

/* ================= SCRIPT MODE ================= */
let currentScript = 'ur';
function setScriptMode(mode) {
  currentScript = mode;
  ['btnScriptUrdu', 'btnScriptDev', 'btnScriptRo', 'btnScriptAscii'].forEach(id => {
    const el = document.getElementById(id);
    if(el) {
      el.classList.toggle('on', (id === 'btnScriptUrdu' && mode === 'ur') ||
                                (id === 'btnScriptDev' && mode === 'hi') ||
                                (id === 'btnScriptRo' && mode === 'ro') ||
                                (id === 'btnScriptAscii' && mode === 'ascii'));
    }
  });

  renderHandbook();
  renderExercises();
  renderDictionary();
  renderFams();
  runStudioScan();
}

/* ================= HANDBOOK VIEWER ================= */
let currentHbChapter = 'ch0';
function renderHandbook() {
  const chips = $('hbChapterChips');
  if(!chips) return;
  chips.innerHTML = HANDBOOK_DATA.map(ch => `
    <button class="fchip ${ch.id === currentHbChapter ? 'on' : ''}" onclick="pickHbChapter('${ch.id}')">
      ${ch.title}
    </button>
  `).join('');

  const view = $('hbChapterView');
  if(!view) return;
  const ch = HANDBOOK_DATA.find(x => x.id === currentHbChapter) || HANDBOOK_DATA[0];
  view.innerHTML = `
    <div style="border-bottom:1px solid var(--line2);padding-bottom:14px;margin-bottom:18px;">
      <div class="row" style="margin:0;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px;">
        <div>
          <span class="pill shape">CHAPTER ${ch.id.replace('ch','')}</span>
          <h1 style="margin:8px 0 4px 0;font-size:24px;color:var(--gold);">${ch.title}</h1>
          <div class="muted small">${ch.filename} · Complete unabridged text from Frances Pritchett & Kh. A. Khaliq Anjum</div>
        </div>
        <div style="font-family:'Jameel Noori Nastaleeq', 'Noto Nastaliq Urdu', serif;font-size:24px;color:var(--teal);direction:rtl;">
          ${ch.urdu_title}
        </div>
      </div>
    </div>
    <div class="hb-verbatim" style="line-height:1.8;font-size:15px;color:var(--ink);">
      ${ch.html_content}
    </div>
  `;

  // Internal link navigation
  view.querySelectorAll('a').forEach(a => {
    const href = a.getAttribute('href');
    if(href && href.startsWith('#')) {
      a.onclick = (e) => {
        e.preventDefault();
        const target = view.querySelector(`[name="${href.slice(1)}"]`) || view.querySelector(href);
        if(target) target.scrollIntoView({behavior:'smooth'});
      };
    } else if(href && href.endsWith('.html')) {
      const matchCh = HANDBOOK_DATA.find(c => href.includes(c.filename));
      if(matchCh) {
        a.onclick = (e) => {
          e.preventDefault();
          pickHbChapter(matchCh.id);
        };
      }
    }
  });
}

function pickHbChapter(id) {
  currentHbChapter = id;
  renderHandbook();
  if(typeof window.scrollTo === 'function') window.scrollTo(0, 0);
}

/* ================= EXERCISES MODULE ================= */
let currentExId = 1;
function renderExercises() {
  const chips = $('exPoetChips');
  if(!chips) return;
  chips.innerHTML = EXERCISES_DATA.map(ex => `
    <button class="fchip ${ex.id === currentExId ? 'on' : ''}" onclick="pickExercise(${ex.id})">
      ${ex.id}. ${ex.poet}
    </button>
  `).join('');

  const ex = EXERCISES_DATA.find(x => x.id === currentExId) || EXERCISES_DATA[0];
  const view = $('exDetailView');
  if(!view) return;
  const meterNum = ex.meters ? ex.meters.join(', #') : '';
  const mi = (ex.notes && ex.notes.meter_info) ? ex.notes.meter_info : '';
  const meterDisplay = mi ? (mi.startsWith('#') ? mi : ('#' + meterNum + ' — ' + mi)) : ('#' + meterNum);
  const introNotes = (ex.notes && ex.notes.intro) ? ex.notes.intro : '';
  const cCount = ex.couplets_count || Math.floor(ex.lines.length / 2);
  const isRtl = (currentScript === 'ur');

  const coupletsHtml = [];
  for(let c = 0; c < cCount; c++) {
    const l1 = ex.lines[2 * c];
    const l2 = ex.lines[2 * c + 1];
    if(!l1 || !l2) continue;
    const verseNum = c + 1;
    const vNote = (ex.notes && ex.notes.verses && ex.notes.verses[verseNum]) ? ex.notes.verses[verseNum] : null;
    const disp1 = getLineDisplay(l1, currentScript);
    const disp2 = getLineDisplay(l2, currentScript);

    let out = `
      <div class="card" style="margin-bottom:14px;background:var(--bg2);">
        <div class="row" style="margin:0 0 10px 0;justify-content:space-between;align-items:center;">
          <span class="pill count">Sher / Couplet ${verseNum} of ${cCount}</span>
          <div class="row" style="margin:0;gap:6px;">
            <button class="btn ghost sm" onclick="loadCoupletInStudio(${ex.id}, ${c})">✍ Scan in Studio</button>
            <button class="btn sm" onclick="playCoupletRhythm(${ex.id}, ${c})">♫ Play Rhythm</button>
          </div>
        </div>

        <div style="display:flex;flex-direction:column;gap:8px;padding:4px 0;">
          <div class="row" style="margin:0;justify-content:space-between;align-items:center;background:var(--bg3);padding:10px 14px;border-radius:6px;gap:12px;">
            <span class="muted tiny">${2 * c + 1}</span>
            <div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:20px;direction:rtl;' : 'font-size:16px;direction:ltr;'}flex:1;text-align:${isRtl ? 'right' : 'left'};">${disp1}</div>
            <button class="btn ghost sm" onclick="scanLineInEngine('${(l1.ur || l1.ascii).replace(/'/g, "\\'")}')">✎ Scan</button>
          </div>
          <div class="row" style="margin:0;justify-content:space-between;align-items:center;background:var(--bg3);padding:10px 14px;border-radius:6px;gap:12px;">
            <span class="muted tiny">${2 * c + 2}</span>
            <div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:20px;direction:rtl;' : 'font-size:16px;direction:ltr;'}flex:1;text-align:${isRtl ? 'right' : 'left'};">${disp2}</div>
            <button class="btn ghost sm" onclick="scanLineInEngine('${(l2.ur || l2.ascii).replace(/'/g, "\\'")}')">✎ Scan</button>
          </div>
        </div>`;

    if(vNote) {
      out += `
        <div style="margin-top:10px;padding:10px 14px;background:var(--bg);border-radius:6px;font-size:13.5px;color:var(--dim);border-left:3px solid var(--gold);line-height:1.65;">
          <strong style="color:var(--gold);">📖 Pritchett's Scansion Note for Verse ${verseNum}:</strong>
          <div style="margin-top:4px;">${vNote}</div>
        </div>`;
    }

    out += `</div>`;
    coupletsHtml.push(out);
  }

  view.innerHTML = `
    <div style="border-bottom:1px solid var(--line2);padding-bottom:16px;margin-bottom:16px;">
      <div class="row" style="margin:0;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px;">
        <div>
          <span class="pill count">Ghazal ${ex.id} of 24</span>
          <h2 style="margin:6px 0 2px 0;font-size:22px;color:var(--gold);">${ex.poet}</h2>
          <div class="muted small">Meter: <strong>${meterDisplay}</strong></div>
        </div>
        <div class="row" style="margin:0;gap:8px;">
          <button class="btn sm" onclick="loadExInScan(${ex.id})">Load into Scansion Engine ✎</button>
          <button class="btn sm gold" onclick="loadExInStudio(${ex.id})">Load into Studio ✍</button>
        </div>
      </div>
      ${introNotes ? `<div class="card" style="margin-top:14px;background:var(--bg2);font-size:14px;line-height:1.65;border-left:3px solid var(--teal);">
        <strong style="color:var(--teal);">📖 Frances Pritchett's Metrical Notes & Context:</strong>
        <div style="margin-top:6px;">${introNotes}</div>
      </div>` : ''}
    </div>

    <div style="display:flex;flex-direction:column;gap:10px;">
      ${coupletsHtml.join('')}
    </div>
  `;
}

function pickExercise(id) {
  currentExId = id;
  renderExercises();
}

function loadCoupletInStudio(exId, c) {
  const ex = EXERCISES_DATA.find(x => x.id === exId);
  if(!ex) return;
  const l1 = ex.lines[2 * c];
  const l2 = ex.lines[2 * c + 1];
  if(!l1 || !l2) return;
  go('studio');
  $('studioInput').value = `${l1.ur}\n${l2.ur}`;
  runStudioScan();
}

function loadExInStudio(exId) {
  const ex = EXERCISES_DATA.find(x => x.id === exId);
  if(!ex) return;
  go('studio');
  $('studioInput').value = ex.lines.map(l => l.ur).join('\n');
  runStudioScan();
}

function playCoupletRhythm(exId, c) {
  if(!A.ensure()) return;
  const ex = EXERCISES_DATA.find(x => x.id === exId);
  if(!ex) return;
  const l1 = ex.lines[2 * c];
  const l2 = ex.lines[2 * c + 1];
  if(!l1 || !l2) return;

  const r1 = Scan.scanLine(l1.ur);
  const r2 = Scan.scanLine(l2.ur);
  if(r1.fits.length && r2.fits.length) {
    const e1 = Scan.explain(r1, r1.fits[0]);
    const p1 = exSeq(e1);
    const e2 = Scan.explain(r2, r2.fits[0]);
    const p2 = exSeq(e2);
    play(p1.seq, {
      feet: p1.feet,
      cae: p1.cae,
      onEnd: () => {
        setTimeout(() => {
          play(p2.seq, { feet: p2.feet, cae: p2.cae });
        }, 350);
      }
    });
  }
}

function loadExInScan(id) {
  const ex = EXERCISES_DATA.find(x => x.id === id);
  if(!ex) return;
  go('scan');
  $('scanIn').value = ex.lines.map(l => l.ur).join('\n');
  runScan();
}

function scanLineInEngine(line) {
  go('scan');
  $('scanIn').value = line;
  runScan();
}

/* ================= DICTIONARY MODULE ================= */
let currentDictTag = 'all';
let currentDictQuery = '';

function renderDictionary() {
  const list = $('dictList');
  if(!list) return;

  const q = currentDictQuery.toLowerCase().trim();
  const filtered = GLOSSARY_DATA.filter(item => {
    if(currentDictTag === 'flex' && !item.wt.includes('x')) return false;
    if(currentDictTag === 'persian' && !item.mean.toLowerCase().includes('pers')) return false;
    if(currentDictTag === 'indic' && !item.mean.toLowerCase().includes('indic')) return false;
    if(!q) return true;
    return item.syl.toLowerCase().includes(q) || item.ascii.toLowerCase().includes(q) || item.mean.toLowerCase().includes(q);
  });

  list.innerHTML = filtered.slice(0, 180).map(item => `
    <div class="card" style="margin:0;background:var(--bg2);display:flex;flex-direction:column;justify-content:space-between;">
      <div>
        <div class="row" style="margin:0;justify-content:space-between;align-items:flex-start;">
          <span style="font-family:monospace;font-size:15px;color:var(--ink);font-weight:600;">${item.syl}</span>
          <span class="pill count" style="font-size:12px;">${item.wt}</span>
        </div>
        <div style="margin-top:6px;font-size:13px;color:var(--dim);line-height:1.5;">${item.mean}</div>
      </div>
      <div class="row" style="margin-top:12px;margin-bottom:0;justify-content:space-between;align-items:center;">
        <span class="muted tiny">${item.ascii ? ' + item.ascii + ' : ''}</span>
        <button class="btn ghost sm" onclick="playWordRhythm('${item.wt}')">♫ Rhythm</button>
      </div>
    </div>
  `).join('');
}

function onDictSearch() {
  currentDictQuery = $('dictSearchInput').value;
  renderDictionary();
}

function filterDictTag(tag) {
  currentDictTag = tag;
  ['dictTagAll', 'dictTagFlex', 'dictTagPersian', 'dictTagIndic'].forEach(id => {
    const el = $(id);
    if(el) el.classList.remove('on');
  });
  if(tag === 'all') $('dictTagAll').classList.add('on');
  if(tag === 'flex') $('dictTagFlex').classList.add('on');
  if(tag === 'persian') $('dictTagPersian').classList.add('on');
  if(tag === 'indic') $('dictTagIndic').classList.add('on');
  renderDictionary();
}

function playWordRhythm(wt) {
  if(!A.ensure()) return;
  const seq = [];
  const parts = wt.replace(/[()]/g, '').split(/[\s,]+/);
  parts.forEach(p => {
    if(p === '=') seq.push('l');
    else if(p === '-') seq.push('s');
    else if(p === 'x') seq.push('l');
  });
  if(seq.length) play(seq);
}

/* ================= STUDIO / COMPOSER MODULE ================= */
let studioTimer = null;
let lastStudioResults = [];

function onStudioInput() {
  clearTimeout(studioTimer);
  studioTimer = setTimeout(runStudioScan, 200);
}

function studioClear() {
  $('studioInput').value = '';
  $('studioResults').innerHTML = '';
  lastStudioResults = [];
}

function runStudioScan() {
  const text = $('studioInput').value.trim();
  const resDiv = $('studioResults');
  if(!text) {
    resDiv.innerHTML = '';
    lastStudioResults = [];
    return;
  }

  const rawLines = text.split('\n').map(l => l.trim()).filter(Boolean);
  if(!rawLines.length) {
    resDiv.innerHTML = '';
    lastStudioResults = [];
    return;
  }

  // Pre-process lines with known index or transliteration fallback
  const lineScans = rawLines.map(rawL => {
    const nk = normVerseKey(rawL);
    let urduL = rawL;
    let lineObj = null;

    if(KNOWN_VERSES[nk]) {
      lineObj = KNOWN_VERSES[nk];
      urduL = lineObj.ur;
    } else if(/[\u0600-\u06FF]/.test(rawL)) {
      urduL = rawL;
      lineObj = { ur: rawL, hi: urduToDevanagari(rawL), ro: urduToRoman(rawL), ascii: rawL };
    } else if(/[\u0900-\u097F]/.test(rawL)) {
      const asc = devToAscii(rawL);
      let ur = '';
      try { if(window.p_ur) ur = window.p_ur.parse(asc); } catch(e){}
      let ro = '';
      try { if(window.p_di) ro = window.p_di.parse(asc); } catch(e){}
      urduL = ur || rawL;
      lineObj = { ur: urduL, hi: rawL, ro: ro || rawL, ascii: asc };
    } else {
      const asc = romanToAscii(rawL);
      let ur = '';
      try { if(window.p_ur) ur = window.p_ur.parse(asc); } catch(e){}
      let hi = '';
      try { if(window.p_hi) hi = window.p_hi.parse(asc); } catch(e){}
      let ro = '';
      try { if(window.p_di) ro = window.p_di.parse(asc); } catch(e){}
      urduL = ur || rawL;
      lineObj = { ur: urduL, hi: hi || rawL, ro: ro || rawL, ascii: asc };
    }

    const res = Scan.scanLine(urduL);
    return { raw: rawL, urdu: urduL, lineObj: lineObj, res: res };
  });

  lastStudioResults = lineScans.map(ls => ({
    res: ls.res,
    lineObj: ls.lineObj,
    best: (ls.res.fits && ls.res.fits.length) ? ls.res.fits[0] : null
  }));

  // Couplet / Stacking evaluation
  let common = null;
  if(lineScans.length > 1) {
    const PAIRS = [[1, 9], [14, 15], [16, 17], [18, 19], [33, 34]];
    const inPair = new Set(PAIRS.flat());
    const groups = Scan.METERS.map(m => m.id).filter(id => !inPair.has(id)).map(id => [id]).concat(PAIRS).concat([['H']]);
    const tot = groups.map(g => {
      let c = 0, fits = [];
      for(const ls of lineScans) {
        const f = ls.res.fits.filter(x => g.includes(x.meter.id)).sort((a, b) => a.c - b.c)[0];
        if(!f) return null;
        c += f.c;
        fits.push(f);
      }
      return { id: g[0], group: g, c, fits };
    }).filter(Boolean).sort((a, b) => a.c - b.c);

    common = tot[0] || null;
    if(common) {
      common.fits.forEach((f, idx) => {
        if(lastStudioResults[idx]) lastStudioResults[idx].best = f;
      });
    }
  }

  let htmlOut = '';

  // 1. Couplet / Multiline banner
  if(lineScans.length > 1) {
    if(common) {
      const avgCost = common.c / lineScans.length;
      const [vc, vt] = verdictOf(avgCost);
      const isPaired = common.group.length > 1;
      htmlOut += `
        <div class="card" style="border-left:4px solid var(--ok);background:var(--bg2);margin-bottom:16px;">
          <div class="row" style="margin:0;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
            <div>
              <div class="row" style="margin:0;gap:8px;align-items:center;">
                <span class="pill shape">COUPLET VERDICT: ${vt}</span>
                ${isPaired ? '<span class="pill count">Paired Meters #' + common.group.join(' ↔ #') + '</span>' : ''}
              </div>
              <h3 style="margin:8px 0 2px 0;color:var(--gold);font-size:20px;">${meterLabel(common.fits[0].meter)}</h3>
              <div class="muted small">${isPaired ? 'Classic paired meters (one long ↔ two shorts near line end) used together in one poem' : 'Both misras share this exact metrical form'}</div>
            </div>
            <button class="btn sm gold" onclick="studioPlayCouplet()">▶ Play Couplet Rhythm</button>
          </div>
        </div>`;
    } else {
      htmlOut += `
        <div class="card" style="border-left:4px solid var(--warn);background:var(--bg2);margin-bottom:16px;">
          <div class="row" style="margin:0;color:var(--gold);font-weight:600;">⚠️ Differing or Strained Meters Between Lines</div>
          <div class="muted small" style="margin-top:6px;">The entered lines do not share a common classical meter or paired family. Inspect individual misras below.</div>
        </div>`;
    }
  }

  // 2. Individual Line Cards
  lineScans.forEach((ls, li) => {
    const best = lastStudioResults[li] ? lastStudioResults[li].best : null;
    const misraTitle = lineScans.length === 2 ? (li === 0 ? 'Misra 1 (مصرع اول / Ūlā)' : 'Misra 2 (مصرع دوم / S̱ānī)') : `Line ${li + 1}`;
    
    // Display in currentScript
    const dispLine = getLineDisplay(ls.lineObj, currentScript);
    const isRtl = (currentScript === 'ur');

    if(!best) {
      htmlOut += `
        <div class="card" style="border-left:3px solid var(--no);background:var(--bg2);margin-bottom:14px;">
          <div class="row" style="margin:0;justify-content:space-between;align-items:center;">
            <span class="pill count">${misraTitle}</span>
            <span class="pill no">NO MATCH</span>
          </div>
          <div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:22px;direction:rtl;' : 'font-size:17px;'}margin:10px 0;">${dispLine}</div>
          <div class="muted small" style="margin-top:6px;">⚠️ Does not match any of the 37 classical meters. Check for surplus syllables, missing flexible words, or 3 consecutive shorts (---).</div>
        </div>`;
      return;
    }

    const expl = Scan.explain(ls.res, best);
    const [vc, vt] = verdictOf(best.c);

    htmlOut += `
      <div class="card" style="border-left:3px solid var(--${vc});background:var(--bg2);margin-bottom:14px;">
        <div class="row" style="margin:0;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
          <div>
            <div class="row" style="margin:0;gap:8px;align-items:center;">
              <span class="pill count">${misraTitle}</span>
              <span class="pill ${vc}">${vt}</span>
            </div>
            <h4 style="margin:6px 0 2px 0;color:var(--gold);font-size:17px;">${meterLabel(best.meter)}</h4>
            <div class="muted tiny">${best.meter.raw || ''}</div>
          </div>
          <button class="btn sm" onclick="studioPlayLine(${li})">▶ Play Line Rhythm</button>
        </div>

        <div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:22px;direction:rtl;' : 'font-size:17px;'}margin:12px 0;padding:8px 0;border-top:1px solid var(--line2);border-bottom:1px solid var(--line2);">
          ${dispLine}
        </div>

        <div style="background:var(--bg3);padding:14px;border-radius:8px;">
          <div class="row" style="margin:0;gap:8px;flex-wrap:wrap;justify-content:center;">
            ${expl.syl.map(s => `
              <div style="display:flex;flex-direction:column;align-items:center;background:var(--bg2);padding:6px 10px;border-radius:6px;min-width:44px;border:1px solid var(--line);">
                <span style="font-family:'Jameel Noori Nastaleeq', 'Noto Nastaliq Urdu', serif;font-size:18px;">${s.text || '·'}</span>
                <span class="pill ${s.resolved === 'l' ? 'shape' : (s.resolved === 'c' ? 'faint' : 'count')}" style="margin-top:4px;font-size:12px;">${s.resolved === 'l' ? '=' : (s.resolved === 'c' ? 'c' : '-')}</span>
                <span class="muted tiny" style="margin-top:2px;font-size:10px;">${s.fsyl || ''}</span>
              </div>
            `).join('')}
          </div>
        </div>

        ${expl.notes && expl.notes.length ? `
          <div style="margin-top:10px;padding:8px 12px;background:var(--bg);border-radius:6px;font-size:12.5px;color:var(--dim);">
            <strong style="color:var(--gold);">Prosodic flexibilities detected:</strong>
            <ul style="margin:4px 0 0 16px;padding:0;">
              ${expl.notes.map(n => `<li>${n.word ? '<strong>' + n.word + '</strong>: ' : ''}${n.note}</li>`).join('')}
            </ul>
          </div>` : ''}
      </div>`;
  });

  resDiv.innerHTML = htmlOut;
}

function studioPlayLine(idx) {
  if(!A.ensure()) return;
  const item = lastStudioResults[idx];
  if(!item || !item.best) return;
  const expl = Scan.explain(item.res, item.best);
  playEx(expl);
}

function studioPlayCouplet() {
  if(!A.ensure()) return;
  if(!lastStudioResults || !lastStudioResults.length) {
    runStudioScan();
  }
  if(!lastStudioResults || !lastStudioResults.length) return;

  const validLines = [];
  lastStudioResults.forEach((item, idx) => {
    if(item && item.best) {
      const expl = Scan.explain(item.res, item.best);
      const pat = exSeq(expl);
      validLines.push({ idx, pat });
    }
  });

  if(!validLines.length) return;

  function playAt(i) {
    if(i >= validLines.length) return;
    const cur = validLines[i];
    play(cur.pat.seq, {
      feet: cur.pat.feet,
      cae: cur.pat.cae,
      onEnd: () => {
        if(i + 1 < validLines.length) {
          setTimeout(() => playAt(i + 1), 350);
        }
      }
    });
  }

  playAt(0);
}

function studioPlayRhythm() {
  studioPlayCouplet();
}


/* ================= AUDIO ================= */
const VOICEPACK={"da": [{"b64": "", "off": 0.12, "dur": 0.6089}, {"b64": "", "off": 0.0901, "dur": 0.5391}, {"b64": "", "off": 0.12, "dur": 0.579}], "dum": [{"b64": "", "off": 0.1, "dur": 0.579}, {"b64": "", "off": 0.0851, "dur": 0.6139}, {"b64": "", "off": 0.0901, "dur": 0.6688}, {"b64": "", "off": 0.0851, "dur": 0.8434}, {"b64": "", "off": 0.0901, "dur": 0.4892}]};
const SOUNDS=[
  {id:'rec',nm:'recorded voice',ds:'real "da" and "dum", several takes, placed exactly on the beat'},
  {id:'mine',nm:'your voice',ds:'record "dum" and "da" once — played back in time'},
  {id:'dumda',nm:'dum · da',ds:'sung syllables — long "dum", short "da"'},
  {id:'daada',nm:'daa · da',ds:'held vowel for long, clipped for short'},
  {id:'tabla',nm:'dhā · tā',ds:'tabla — bass stroke for long, rim for short'},
  {id:'tone',nm:'tone',ds:'plain low / high tones'}
];
const settings=store.get('settings',{sound:'rec',bpm:150});
if(!settings.v6){ settings.sound='rec'; settings.bpm=150; settings.v6=1; store.set('settings',settings); }
const A={ctx:null,out:null,noise:null,timers:[],
  ensure(){
    if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext; if(!C)return false;
      this.ctx=new C();
      const comp=this.ctx.createDynamicsCompressor(); comp.threshold.value=-20; comp.knee.value=12; comp.ratio.value=5;
      const mk=this.ctx.createGain(); mk.gain.value=1.6;
      this.out=this.ctx.createGain(); this.out.gain.value=0.9; this.out.connect(comp); comp.connect(mk); mk.connect(this.ctx.destination);
      const len=Math.floor(this.ctx.sampleRate*1.0), b=this.ctx.createBuffer(1,len,this.ctx.sampleRate), d=b.getChannelData(0);
      for(let i=0;i<len;i++)d[i]=Math.random()*2-1; this.noise=b;
      /* small room: decaying stereo noise impulse */
      try{ const rl=Math.floor(this.ctx.sampleRate*1.1), ir=this.ctx.createBuffer(2,rl,this.ctx.sampleRate);
        for(let ch=0;ch<2;ch++){const x=ir.getChannelData(ch); for(let i=0;i<rl;i++) x[i]=(Math.random()*2-1)*Math.pow(1-i/rl,3.2);}
        const cv=this.ctx.createConvolver(); cv.buffer=ir; const wet=this.ctx.createGain(); wet.gain.value=0.22;
        this.voiceBus=this.ctx.createGain(); this.voiceBus.connect(this.out); this.voiceBus.connect(cv); cv.connect(wet); wet.connect(this.out);
      }catch(e){ this.voiceBus=this.out; }
      /* glottal pulse spectrum: harmonics falling ~12 dB/octave, like a relaxed singing voice */
      try{ const N=48, re=new Float32Array(N), im=new Float32Array(N); for(let k=1;k<N;k++) im[k]=Math.pow(k,-1.25)*(k%2?1:0.85);
        this.glottal=this.ctx.createPeriodicWave(re,im,{disableNormalization:false}); }catch(e){ this.glottal=null; }
      loadMine(); loadRec();}
    if(this.ctx.state==='suspended')this.ctx.resume();
    return true;
  },
  unlock(){ if(!this.ensure())return; try{const s=this.ctx.createBufferSource(); s.buffer=this.ctx.createBuffer(1,1,22050); s.connect(this.ctx.destination); s.start(0);}catch(e){} }
};
document.addEventListener('pointerdown',()=>A.unlock(),{once:true,passive:true});

function burst(t,freq,q,vol,dur,dest){
  const c=A.ctx, n=c.createBufferSource(); n.buffer=A.noise;
  const f=c.createBiquadFilter(); f.type='bandpass'; f.frequency.value=freq; f.Q.value=q;
  const g=c.createGain(); g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.0005,t+dur);
  n.connect(f); f.connect(g); g.connect(dest||A.dest||A.out); n.start(t); n.stop(t+dur+0.01);
}
/* sung syllable: glottal source → vowel formants, /d/ burst with pre-voicing, vibrato, breath, room.
   ctx.contour (0..1 position in the line) gives the phrase a gentle sung rise and fall. */
function voice(t,dur,isLong,style,vol,pos){
  const c=A.ctx, sound=Math.max(0.1,dur*0.9);
  const phrase = 1 + 0.05*Math.sin(Math.PI*Math.min(1,pos||0)) - (pos>0.92?0.04:0);
  const f0=(isLong?117:124)*phrase*(1+(Math.random()-0.5)*0.02);
  const osc=c.createOscillator(); if(A.glottal) osc.setPeriodicWave(A.glottal); else osc.type='sawtooth';
  osc.frequency.setValueAtTime(f0*0.97,t); osc.frequency.linearRampToValueAtTime(f0,t+0.06);
  osc.frequency.linearRampToValueAtTime(f0*(isLong?0.985:0.99),t+sound);
  /* vibrato that blooms on long notes */
  const lfo=c.createOscillator(), lg=c.createGain(); lfo.frequency.value=5.3+Math.random()*0.5;
  lg.gain.setValueAtTime(0,t); lg.gain.linearRampToValueAtTime(isLong?f0*0.014:f0*0.004,t+Math.min(0.35,sound));
  lfo.connect(lg); lg.connect(osc.frequency);
  const src=c.createGain(); osc.connect(src);
  /* breath */
  const br=c.createBufferSource(); br.buffer=A.noise; br.loop=true;
  const bf=c.createBiquadFilter(); bf.type='bandpass'; bf.frequency.value=1600; bf.Q.value=0.6;
  const bg=c.createGain(); bg.gain.value=0.05; br.connect(bf); bf.connect(bg); bg.connect(src);
  const env=c.createGain(); env.gain.value=0; env.connect(A.dest||A.voiceBus||A.out);
  const V = (style==='dumda'&&isLong) ? [{f:640,b:80,g:1},{f:1150,b:100,g:0.55},{f:2450,b:150,g:0.24},{f:3400,b:220,g:0.08}]
                                      : [{f:760,b:90,g:1},{f:1250,b:110,g:0.6},{f:2600,b:160,g:0.22},{f:3500,b:220,g:0.08}];
  const nodes=V.map(x=>{const bp=c.createBiquadFilter(); bp.type='bandpass'; bp.Q.value=x.f/x.b; bp.frequency.value=x.f;
    const g=c.createGain(); g.gain.value=x.g; src.connect(bp); bp.connect(g); g.connect(env); return {bp,g,x};});
  /* dental d: F1 rises from closure, F2 falls from ~1700 */
  nodes[0].bp.frequency.setValueAtTime(300,t); nodes[0].bp.frequency.linearRampToValueAtTime(V[0].f,t+0.05);
  nodes[1].bp.frequency.setValueAtTime(1700,t); nodes[1].bp.frequency.linearRampToValueAtTime(V[1].f,t+0.06);
  /* pre-voicing murmur (Urdu d is voiced through the closure) */
  const pv=c.createBiquadFilter(); pv.type='lowpass'; pv.frequency.value=320; const pg=c.createGain();
  pg.gain.setValueAtTime(0,t); pg.gain.linearRampToValueAtTime(0.9*vol,t+0.008); pg.gain.linearRampToValueAtTime(0,t+0.03);
  src.connect(pv); pv.connect(pg); pg.connect(env);
  const pk=(isLong?3.3:3.0)*vol;
  env.gain.setValueAtTime(0,t); env.gain.linearRampToValueAtTime(pk*0.35,t+0.012); env.gain.linearRampToValueAtTime(pk,t+0.04);
  if(style==='dumda' && isLong){                       /* close into a hummed m */
    const m=t+sound*0.55;
    nodes[0].bp.frequency.setValueAtTime(V[0].f,m); nodes[0].bp.frequency.linearRampToValueAtTime(260,m+0.06);
    [1,2,3].forEach(i=>{ nodes[i].g.gain.setValueAtTime(V[i].g,m); nodes[i].g.gain.linearRampToValueAtTime(0.02,m+0.06); });
    env.gain.setValueAtTime(pk,m); env.gain.linearRampToValueAtTime(pk*0.85,m+0.07);
    bg.gain.setValueAtTime(0.05,m); bg.gain.linearRampToValueAtTime(0.0,m+0.06);
  } else if(isLong){ env.gain.setValueAtTime(pk,t+sound*0.6); env.gain.linearRampToValueAtTime(pk*0.8,t+sound-0.05); }
  env.gain.setTargetAtTime(0,t+sound-0.04,0.03);
  const end=t+sound+0.25;
  osc.start(t); osc.stop(end); lfo.start(t); lfo.stop(end); br.start(t); br.stop(end);
  burst(t+0.004,3100,0.9,0.28*vol,0.018);
}
/* ---------- recorded voice pack ---------- */
function loadRec(){
  if(A.recP) return A.recP;
  const dec=o=>{ const bin=atob(o.b64), u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    return new Promise((res)=>{ try{ const p=A.ctx.decodeAudioData(u.buffer,b=>res({buf:b,off:o.off,dur:o.dur}),()=>res(null)); if(p&&p.then)p.catch(()=>res(null)); }catch(e){res(null);} }); };
  A.recP=Promise.all([Promise.all(VOICEPACK.da.map(dec)),Promise.all(VOICEPACK.dum.map(dec))])
    .then(([da,dum])=>{ A.rec={da:da.filter(Boolean),dum:dum.filter(Boolean),last:{l:-1,s:-1}}; });
  return A.recP;
}
/* choose the take whose sounding length best fits the slot, never the same take twice running */
function recSound(t,dur,isLong,vol,pos,holdF){
  const R=A.rec; if(!R||!R.da.length||!R.dum.length) return voice(t,dur,isLong,'dumda',vol,pos);
  const pool=isLong?R.dum:R.da, key=isLong?'l':'s';
  let bi=0,bs=1e9; pool.forEach((k,j)=>{ const sc=Math.abs((k.dur-k.off)-dur*0.95)+(j===R.last[key]?0.2:0); if(sc<bs){bs=sc;bi=j;} });
  R.last[key]=bi; const k=pool[bi];
  const rate=1+0.02*Math.sin(Math.PI*Math.min(1,pos||0))-((pos||0)>0.9?0.02:0);
  const c=A.ctx, src=c.createBufferSource(); src.buffer=k.buf; src.playbackRate.value=rate;
  const g=c.createGain(); const start=Math.max(c.currentTime, t-k.off/rate);
  const hold=Math.min(k.dur/rate, k.off/rate+dur*0.95), fo=Math.min(0.05,hold/3);
  g.gain.setValueAtTime(vol,start); g.gain.setValueAtTime(vol,start+hold-fo); g.gain.linearRampToValueAtTime(0,start+hold);
  src.connect(g); g.connect(A.dest||A.voiceBus||A.out); src.start(start); src.stop(start+hold+0.02);
}
/* ---------- your own voice ---------- */
const mine={dum:null,da:null};
const hasMine=k=>!!mine[k]||!!store.get('mine_'+k,null);
function b64ToBuf(b64){ const bin=atob(b64), n=bin.length/2, out=new Float32Array(n);
  for(let i=0;i<n;i++){ let v=bin.charCodeAt(2*i)|(bin.charCodeAt(2*i+1)<<8); if(v>32767)v-=65536; out[i]=v/32768; }
  const buf=A.ctx.createBuffer(1,n,22050); buf.getChannelData(0).set(out); return buf; }
function bufToB64(f32){ let s=''; for(let i=0;i<f32.length;i++){ let v=Math.max(-1,Math.min(1,f32[i]))*32767|0; if(v<0)v+=65536; s+=String.fromCharCode(v&255,v>>8); } return btoa(s); }
function loadMine(){ ['dum','da'].forEach(k=>{ const b=store.get('mine_'+k,null); if(b){ try{ mine[k]=b64ToBuf(b); }catch(e){} } }); }
/* trim silence, normalise, resample to 22.05 kHz, cap at 1.2 s */
function prepClip(ab){
  const d=ab.getChannelData(0), sr=ab.sampleRate; let pk=0; for(let i=0;i<d.length;i++) pk=Math.max(pk,Math.abs(d[i]));
  if(pk<0.02) return null;
  let a=0; while(a<d.length && Math.abs(d[a])<pk*0.12) a++; a=Math.max(0,a-Math.floor(sr*0.012));
  let z=d.length-1; while(z>a && Math.abs(d[z])<pk*0.06) z--; z=Math.min(d.length-1,z+Math.floor(sr*0.05));
  const ratio=sr/22050, n=Math.min(Math.floor((z-a)/ratio), 22050*1.2|0), out=new Float32Array(n);
  for(let i=0;i<n;i++) out[i]=d[a+Math.floor(i*ratio)]*(0.9/pk);
  const f=Math.min(n,Math.floor(22050*0.03)); for(let i=0;i<f;i++) out[n-1-i]*=i/f;   /* soft tail */
  return out;
}
function saveClip(k,f32){ const b=bufToB64(f32); store.set('mine_'+k,b); mine[k]=b64ToBuf(b); renderSoundOpts(); }
async function recordClip(k){
  A.ensure(); const st=$('recStatus');
  if(!navigator.mediaDevices||!window.MediaRecorder){ st.textContent='Recording isn\'t available here — use "choose files" instead.'; return; }
  let stream; try{ stream=await navigator.mediaDevices.getUserMedia({audio:true}); }
  catch(e){ st.textContent='Microphone blocked here — use "choose files" (a voice memo works).'; return; }
  const rec=new MediaRecorder(stream), chunks=[]; rec.ondataavailable=e=>chunks.push(e.data);
  rec.onstop=async()=>{ stream.getTracks().forEach(t=>t.stop());
    try{ const ab=await A.ctx.decodeAudioData(await new Blob(chunks).arrayBuffer()); const clip=prepClip(ab);
      if(!clip){ st.textContent='That was silent — try again a bit closer to the mic.'; return; }
      saveClip(k,clip); st.textContent='Saved "'+k+'". '+(mine.dum&&mine.da?'Both done — listen:':'Now record the other one.');
      if(mine.dum&&mine.da){ settings.sound='mine'; store.set('settings',settings); renderSoundOpts(); play(['l','s','l','l','s','l']); }
    }catch(e){ st.textContent='Couldn\'t read that recording — try "choose files".'; } };
  st.textContent='● Recording — say "'+k+'" now…'; rec.start(); setTimeout(()=>rec.state!=='inactive'&&rec.stop(),1400);
}
async function fileClip(k,input){ A.ensure(); const st=$('recStatus'); const f=input.files&&input.files[0]; if(!f) return;
  try{ const ab=await A.ctx.decodeAudioData(await f.arrayBuffer()); const clip=prepClip(ab);
    if(!clip){ st.textContent='That file seems silent.'; return; } saveClip(k,clip); st.textContent='Loaded "'+k+'".'; }
  catch(e){ st.textContent='Couldn\'t decode that file — try an m4a, mp3 or wav.'; } }
function mineSound(t,dur,isLong,vol){
  const buf=isLong?(mine.dum||mine.da):(mine.da||mine.dum); if(!buf) return voice(t,dur,isLong,'dumda',vol,0);
  const c=A.ctx, s=c.createBufferSource(); s.buffer=buf; const g=c.createGain();
  const hold=Math.min(buf.duration,dur*0.93);
  g.gain.setValueAtTime(vol,t); g.gain.setValueAtTime(vol,t+Math.max(0.02,hold-0.04)); g.gain.linearRampToValueAtTime(0,t+hold);
  s.connect(g); g.connect(A.dest||A.voiceBus||A.out); s.start(t); s.stop(t+hold+0.02);
}
function tabla(t,dur,isLong,vol){
  const c=A.ctx, f=isLong?311:370, decay=isLong?Math.min(0.7,dur*1.1):Math.min(0.2,dur*0.9);
  [1,2,3,4.15].forEach((h,i)=>{const o=c.createOscillator(); o.type='sine'; o.frequency.value=f*h;
    const g=c.createGain(); const d=decay/(1+i*0.7); g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.55*vol/(i+1),t+0.004);
    g.gain.exponentialRampToValueAtTime(0.0006,t+d); o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+d+0.05);});
  burst(t,isLong?2400:4200,1.2,0.35*vol,0.015);
  if(isLong){ const o=c.createOscillator(); o.type='sine'; o.frequency.setValueAtTime(72,t); o.frequency.linearRampToValueAtTime(104,t+Math.min(0.45,dur));
    const g=c.createGain(); g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(1.1*vol,t+0.006); g.gain.exponentialRampToValueAtTime(0.0006,t+Math.min(0.9,dur*1.4));
    o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+1); }
}
function tone(t,dur,isLong,vol){
  const c=A.ctx,o=c.createOscillator(),g=c.createGain(); o.type='triangle'; o.frequency.value=isLong?392:587;
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.8*vol,t+0.01); g.gain.exponentialRampToValueAtTime(0.0005,t+dur*0.9);
  o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+dur);
}
function tick(){ if(!A.ensure())return; const t=A.ctx.currentTime+0.005; burst(t,2600,2,0.5,0.03,A.out); }
function syllableSound(t,dur,isLong,vol,pos,hold){
  const s=settings.sound, d=dur*(hold||1);
  if(s==='tabla') tabla(t,d,isLong,vol); else if(s==='tone') tone(t,d,isLong,vol);
  else if(s==='mine') mineSound(t,d,isLong,vol); else if(s==='rec') recSound(t,d/0.95,isLong,vol,pos,hold); else voice(t,d,isLong,s,vol,pos);
}
/* soft low drum on each foot's first syllable */
function footThump(t,vol){ const c=A.ctx,o=c.createOscillator(),g=c.createGain(); o.type='sine';
  o.frequency.setValueAtTime(95,t); o.frequency.exponentialRampToValueAtTime(58,t+0.18);
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(0.5*vol,t+0.006); g.gain.exponentialRampToValueAtTime(0.0005,t+0.3);
  o.connect(g); g.connect(A.dest||A.out); o.start(t); o.stop(t+0.32); }
function stopAll(){ A.timers.forEach(clearTimeout); A.timers=[];
  if(A.ctx && A.sess){ const g=A.sess, now=A.ctx.currentTime; try{ g.gain.cancelScheduledValues(now); g.gain.setValueAtTime(g.gain.value,now); g.gain.linearRampToValueAtTime(0,now+0.03); }catch(e){}
    setTimeout(()=>{ try{g.disconnect();}catch(e){} },80); A.sess=null; } }
/* seq of 'l','s','x','c'; onStep(i) fires as each syllable sounds */
function play(seq,opts){
  opts=opts||{}; if(!A.ensure())return 0;
  if(settings.sound==='rec' && !A.rec){ loadRec().then(()=>play(seq,opts)); return (seq.length*1.5*60/settings.bpm); }
  stopAll();
  const sess=A.ctx.createGain(); sess.gain.value=1; sess.connect(A.voiceBus||A.out); A.sess=sess; A.dest=sess;
  const beat=60/(opts.bpm||settings.bpm); let t=A.ctx.currentTime+0.16; const t0=t;
  const F=opts.feet, cae=opts.cae||[];
  seq.forEach((v,i)=>{
    const isLong=(v==='l'||v==='x'); let dur=(isLong?2:1)*beat;
    let vol=v==='c'?0.45:1, hold=0.97;
    if(F){ const fs=(i===0||F[i]!==F[i-1]), fe=(i===seq.length-1||F[i+1]!==F[i]);
      if(fs && i>0 && cae.includes(F[i])) t+=beat*0.6;              /* breath at the mid-line break */
      if(fs && settings.footPulse!==false && v!=='c') footThump(t,0.9);
      if(!fs && v!=='c') vol*=0.84;                                   /* stress the foot's first syllable */
      if(fe && i<seq.length-1){ dur*=1.07; hold=0.82; }               /* a little lift at the end of each foot */
    }
    if(opts.cadence!==false && i===seq.length-1 && seq.length>4) dur*=1.4;
    syllableSound(t,dur,isLong,vol,i/Math.max(1,seq.length-1),hold);
    if(opts.onStep) A.timers.push(setTimeout(()=>opts.onStep(i),(t-A.ctx.currentTime)*1000));
    t+=dur;
  });
  if(opts.onEnd) A.timers.push(setTimeout(opts.onEnd,(t-A.ctx.currentTime)*1000+60));
  return (t-t0);
}
function litter(nodes){ return i=>{ nodes.forEach(n=>n.classList.remove('lit')); const n=nodes[i]; if(n){n.classList.add('lit'); setTimeout(()=>n.classList.remove('lit'),240);} }; }

/* sound sheet */
function openSound(){ renderSoundOpts(); $('soundSheet').classList.add('on'); }
function closeSound(){ $('soundSheet').classList.remove('on'); }
function renderSoundOpts(){
  $('soundOpts').innerHTML=SOUNDS.map(s=>`<div class="sopt ${s.id===settings.sound?'on':''}" onclick="pickSound('${s.id}')"><span class="play">▶︎</span><div style="flex:1"><div class="nm">${s.nm}</div><div class="ds">${s.ds}</div></div></div>`
    + (s.id==='mine'?`<div class="card" style="margin:-2px 0 10px;padding:10px 12px" onclick="event.stopPropagation()">
      <div class="row" style="margin:0">
        <button class="btn sm ${hasMine('dum')?'':'gold'}" onclick="recordClip('dum')">● dum ${hasMine('dum')?'✓':''}</button>
        <button class="btn sm ${hasMine('da')?'':'gold'}" onclick="recordClip('da')">● da ${hasMine('da')?'✓':''}</button>
        <label class="btn sm ghost">dum file<input type="file" accept="audio/*" style="display:none" onchange="fileClip('dum',this)"></label>
        <label class="btn sm ghost">da file<input type="file" accept="audio/*" style="display:none" onchange="fileClip('da',this)"></label>
      </div>
      <p class="tiny muted" id="recStatus" style="margin:6px 0 0">Tap ● and say the syllable once, the way you'd recite — short and clear for "da", a full "dum" for the long. Silence is trimmed automatically; it stays on this device.</p></div>`:'')).join('');
  $('bpm').value=settings.bpm; $('bpmV').textContent=settings.bpm;
}
function pickSound(id){ if(id==='mine' && !(hasMine('dum')||hasMine('da'))){ settings.sound=id; store.set('settings',settings); renderSoundOpts(); $('recStatus').textContent='Record "dum" and "da" first (or choose two audio files).'; return; } settings.sound=id; store.set('settings',settings); renderSoundOpts(); $('soundName').textContent=SOUNDS.find(s=>s.id===id).nm.replace(/ /g,''); play(['l','s','l','l','s','l']); }
$('bpm').addEventListener('input',e=>{settings.bpm=+e.target.value; $('bpmV').textContent=settings.bpm; store.set('settings',settings);});
$('soundName').textContent=SOUNDS.find(s=>s.id===settings.sound).nm.replace(/ /g,'');

