function meterLabel(m){
  if(!m) return '';
  if(m.id==='H') return "Mir's Hindi meter";
  const numStr = m.kind==='rubai' ? ('rubāʿī ' + (''+m.id).replace(/^R/i,'')) : ('Meter #' + m.id);
  const tech = (typeof METERS_DATA !== 'undefined' && METERS_DATA.standard) ? (METERS_DATA.standard.find(x => x.id === m.id) || {}).name : (METER_TECH_NAMES[m.id] || '');
  const f = (typeof famOfMeter !== 'undefined') ? famOfMeter[m.id] : null;

  let famTitle = '';
  if (f && FAM_TITLES[f.id]) famTitle = FAM_TITLES[f.id];
  else if (f && f.gz && f.gz[0]) famTitle = `${f.gz[0].p}'s Bahr`;
  else if (m.id === 26) famTitle = "Vali's Bahr";

  if (famTitle && tech) return `${famTitle} (${numStr}) — ${tech}`;
  if (famTitle) return `${famTitle} (${numStr})`;
  if (tech) return `${numStr} — ${tech}`;
  return numStr;
}
function runScan(){
  const lines=$('scanIn').value.split('\n').map(s=>s.trim()).filter(Boolean);
  if(!lines.length){ $('scanOut').innerHTML=''; return; }
  const results=lines.map((l,i)=>Scan.scanLine(l,ovr[i]));
  lastScan={lines,results};
  let h='';
  /* stacking */
  let common=null;
  if(lines.length>1){
    /* ch.6: paired meters (one long ↔ two shorts near the end) are used together in one poem */
    const PAIRS=[[1,9],[14,15],[16,17],[18,19],[33,34]];
    const inPair=new Set(PAIRS.flat());
    const groups=Scan.METERS.map(m=>m.id).filter(id=>!inPair.has(id)).map(id=>[id]).concat(PAIRS).concat([['H']]);
    const tot=groups.map(g=>{let c=0,fits=[]; for(const r of results){const f=r.fits.filter(x=>g.includes(x.meter.id)).sort((a,b)=>a.c-b.c)[0]; if(!f){return null;} c+=f.c; fits.push(f);} return {id:g[0],group:g,c,fits};}).filter(Boolean).sort((a,b)=>a.c-b.c);
    common=tot[0]||null;
    if(!common){ /* which bahr fits the most lines? */
      let bestG=null; groups.forEach(g=>{ let n=0,c=0; const miss=[]; results.forEach((r,li)=>{const f=r.fits.filter(x=>g.includes(x.meter.id)).sort((a,b)=>a.c-b.c)[0]; if(f){n++;c+=f.c;} else miss.push(li+1);});
        if(n>=2 && (!bestG||n>bestG.n||(n===bestG.n&&c<bestG.c))) bestG={g,n,c,miss}; });
      lastScan.near=bestG; }
    lastScan.forced = common && common.c/lines.length<=5 ? common.fits : null;
    h+=stackHTML(lines,results,common,tot);
  }
  results.forEach((r,li)=>{ h+=lineHTML(r,li,common&&common.c/lines.length<=5?common.fits[li]:null); });
  $('scanOut').innerHTML=h;
}
function stackHTML(lines,results,common,tot){
  if(!common) {
    const nb=lastScan.near; let msg='';
    if(nb){ const f=famOfMeter[nb.g[0]]; const name=f?`<span class="urdu" style="font-size:15px">${famLabel(f).ur}</span>`:(nb.g[0]==='H'?'Mir\'s Hindi meter':'#'+nb.g.join('/'));
      msg=`<p class="small">${nb.n} of ${lines.length} lines fit ${name}. Look closely at line${nb.miss.length>1?'s':''} <b class="t">${nb.miss.join(', ')}</b> — a reading, an unwritten iẓāfat, a missing tashdīd, or the text itself.</p>`; }
    let key=''; if(curEx) key=`<p class="tiny muted">Pritchett's answer key: <b class="t">${curEx.m.map(x=>x==='H'?'Hindi meter':'#'+x).join(' / ')}</b></p>`;
    return `<div class="card"><div class="verdict" style="color:var(--no)">No single bahr fits every line</div>${msg}${key}</div>`;
  }
  const members=[...new Set(common.fits.map(f=>f.meter))].sort((a,b)=>b.seq?(b.seq.length-(a.seq?a.seq.length:0)):0);
  const m=members[0], per=common.c/lines.length, [vc,vt]=verdictOf(per), fam=famOfMeter[m.id];
  const exps=common.fits.map((f,li)=>Scan.explain(results[li],f)), rows=exps.map(e=>e.syl);
  const cell=(s,k,r)=>`<td class="${s.resolved} ${s.native==='x'?'flex':''} ${r&&r[k+1]&&r[k+1].foot!==s.foot?'fend':''}">${s.text}</td>`;
  let head='', body='';
  if(m.id!=='H'){
    const uni=m.seq.slice(); if(m.cheatCae) uni.splice(m.cae,0,'c'); if(m.cheatFinal) uni.push('c');
    head=`<tr><td class="num"></td>${uni.map(t=>`<td class="hd ${t==='c'?'':t}">${t==='l'?'=':t==='s'?'–':t==='x'?'x':'+'}</td>`).join('')}</tr>`;
    /* where a paired meter has one long for two shorts, that cell spans two columns */
    const other=members[1]; let split=-1;
    if(other){ for(let k=0;k<m.seq.length;k++){ if(m.seq[k]!==other.seq[k]){ split=k; break; } } if(split>=0 && m.cheatCae && m.cae<=split) split++; }
    body=rows.map((r,li)=>{ const seq=common.fits[li].seq, short=common.fits[li].meter!==m; let j=0, tds='';
      for(let u=0;u<uni.length;u++){ const t=uni[u];
        if(t==='c' && seq[j]!=='c'){ tds+='<td style="background:transparent"></td>'; continue; }
        if(short && u===split){ tds+= r[j]?cell(r[j],j,r).replace('<td ','<td colspan="2" '):'<td colspan="2"></td>'; j++; u++; continue; }
        tds+= r[j]?cell(r[j],j,r):'<td></td>'; j++; }
      return `<tr><td class="num">${li+1}</td>${tds}</tr>`; }).join('');
    /* feet header from the fullest member */
    const fs=Scan.patternFeet(m.raw); let fh='<tr><td class="num"></td>';
    fs.forEach((f,fi)=>{ let span=f.toks.length; if(m.cheatCae && fs[fi+1] && fs[fi+1].caeBefore) span++; if(fi===fs.length-1 && m.cheatFinal) span++;
      fh+=`<td class="fh" colspan="${span}">${f.ur}<br><i>${f.ro.join('·')}</i></td>`; });
    head=fh+'</tr>'+head;
  } else body=rows.map((r,li)=>`<tr><td class="num">${li+1}</td>${r.map((x,k)=>cell(x,k,r)).join('')}</tr>`).join('');
  const alt=tot.filter(x=>x!==common).slice(0,2).filter(x=>x.c-common.c<1.5).map(x=>famOfMeter[x.id]?`<span class="urdu" style="font-size:14px">${famLabel(famOfMeter[x.id]).ur}</span>`:(x.id==='H'?'Hindi meter':'#'+x.id));
  let key='';
  if(curEx){ const hit=common.fits.every(f=>curEx.m.includes(f.meter.id));
    key=`<div class="card" style="margin:0 0 10px;padding:10px 12px;background:var(--bg3)"><span class="tiny muted">Pritchett's answer key (ch. 11):</span> <b class="t">${curEx.m.map(x=>x==='H'?'Hindi meter':'#'+x).join(' / ')}</b> — ${hit?'<span style="color:var(--ok)">the scanner agrees ✓</span>':'<span style="color:var(--no)">the scanner disagrees ✗</span>'}</div>`; }
  return `<div class="card">${key}<div class="row" style="margin-top:0"><span class="pill ${vc}">${vt}</span><span class="tiny muted">all ${lines.length} lines stacked</span></div>
    ${m.id!=='H'&&!fam?'':''}${fam?`<div class="small muted">Same bahr as</div><div class="fam-name">${famLabel(fam).ur}</div><div class="ro">${famLabel(fam).ro} — ${famLabel(fam).ref}</div>`:`<div class="verdict">${meterLabel(m)}</div>`}
    <div class="grid"><table>${head}${body}</table></div>
    <p class="tiny muted">Columns are metrical positions (right → left, like the text). Pink cells are flexible syllables the meter resolved; dashed cells are unscanned cheat syllables.</p>
    ${alt.length?`<p class="tiny muted">Close runner-up: ${alt.join(' · ')}</p>`:''}
    ${fam?`<div class="row"><button class="btn sm" onclick="go('bahr');document.getElementById('fam-${fam.id}').scrollIntoView()">More ghazals in this bahr ›</button></div>`:''}</div>`;
}
function lineHTML(r,li,forced){
  const f=forced||r.fits[0];
  let h=`<div class="card"><div class="tiny muted">Line ${li+1}</div>`;
  h+=`<div class="words">${r.words.map((w,wi)=>`<button class="wbtn ${selWord&&selWord[0]===li&&selWord[1]===wi?'sel':''} ${ovr[li]&&ovr[li][wi]?'ov':''}" onclick="pickWord(${li},${wi})">${w.raw}</button>`).join('')}</div>`;
  if(selWord&&selWord[0]===li) h+=wordPanel(r,li,selWord[1]);
  if(!f){ h+=`<div class="verdict" style="color:var(--no);margin-top:6px">Doesn't scan as typed</div><p class="small muted">No bahr fits any reading. Tap a word to change its reading, add or remove an iẓāfat, or check the text (a doubled letter without tashdīd is the most common slip).</p></div>`; return h; }
  const e=Scan.explain(r,f), [vc,vt]=verdictOf(f.c), fam=famOfMeter[f.meter.id];
  h+=`<div class="row"><span class="pill ${vc}">${vt}</span>${fam?`<span class="small muted">bahr of</span><span class="urdu" style="font-size:15px;line-height:1.8">${famLabel(fam).ur}</span>`:`<span class="small muted">${meterLabel(f.meter)}</span>`}</div>`;
  h+=`<div class="chips" id="sc${li}">${chipsHTML(e.syl,e.feet)}</div>`;
  if(f.meter.id==='H' && lastScan.lines.length===1) h+=`<p class="tiny X" style="margin:2px 0">Mir's Hindi meter is loose enough that even some ordinary sentences fit it. One line proves little — add the rest of the ghazal.</p>`;
  h+=`<div class="legend"><span><i class="sw" style="background:var(--gold)"></i>long</span><span><i class="sw" style="background:var(--teal)"></i>short</span><span><i class="sw" style="background:color-mix(in srgb,var(--rose) 40%,transparent)"></i>flexible, resolved</span><span><i class="sw" style="border:1.5px dashed var(--ghost)"></i>cheat</span><span>‿ grafted</span></div>`;
  h+=`<div class="row"><button class="btn gold sm" onclick="playScan(${li})">▶︎ Hear it</button></div>`;
  const notes=[...new Set(e.notes.map(n=>`${n.word}: ${n.note}`))].filter(n=>!/: $/.test(n));
  if(notes.length) h+=`<p class="tiny muted" style="margin:4px 0">${notes.join(' · ')}</p>`;
  if(!forced){ const alts=r.fits.slice(1,4).filter(x=>x.c-f.c<1.2); if(alts.length) h+=`<p class="tiny muted">Also fits: ${alts.map(x=>famOfMeter[x.meter.id]?`<span class="urdu" style="font-size:13px">${famLabel(famOfMeter[x.meter.id]).ur}</span>`:meterLabel(x.meter)).join(' · ')} — add the other misra to decide.</p>`; }
  return h+'</div>';
}
function playScan(li){ if(!lastScan||!lastScan.results[li]) return; const r=lastScan.results[li]; const f=(lastScan.forced&&lastScan.forced[li])||r.fits[0];
  if(!f||!$('sc'+li)) return;
  const e=Scan.explain(r,f); const host=$('sc'+li);
  playEx(e,[...host.querySelectorAll('.chip')].sort((a,b)=>a.dataset.i-b.dataset.i),[...host.querySelectorAll('.fgrp')]); }
function pickWord(li,wi){ selWord=(selWord&&selWord[0]===li&&selWord[1]===wi)?null:[li,wi]; runScan(); }
function wordPanel(r,li,wi){
  const w=r.words[wi]; const o=(ovr[li]&&ovr[li][wi])||{};
  const own=Scan.scanWord(w.raw,o.suffix!==undefined?o.suffix:null).opts;
  const wStr=op=>op.syl.map(s=>s.w==='l'?'=':s.w==='s'?'–':'x').join(' ');
  let h=`<div class="card" style="margin:6px 0;background:var(--bg3)"><div class="tiny muted">Readings of <span class="urdu" style="font-size:15px">${w.raw}</span> — pick one, or let the meter choose</div>`;
  h+=`<div class="optrow ${o.opt==null?'on':''}" onclick="setOpt(${li},${wi},null)"><span class="mono small">auto</span><span class="tiny muted">let the bahr decide</span></div>`;
  own.forEach((op,oi)=>{ h+=`<div class="optrow ${o.opt===oi?'on':''}" onclick="setOpt(${li},${wi},${oi})"><span class="mono small" style="min-width:70px">${wStr(op)}</span><span class="tiny muted">${op.n||''}</span></div>`; });
  h+=`<div class="row"><button class="btn sm" onclick="toggleIz(${li},${wi})">${(o.suffix!==undefined?o.suffix:w.suffix)==='iz'?'Remove iẓāfat':'Add iẓāfat ِ'}</button><button class="btn sm" onclick="toggleGraft(${li},${wi})">${o.noGraft?'Allow grafting':'No grafting here'}</button></div></div>`;
  return h;
}
function ens(li,wi){ ovr[li]=ovr[li]||{}; ovr[li][wi]=ovr[li][wi]||{}; return ovr[li][wi]; }
function setOpt(li,wi,oi){ ens(li,wi).opt=oi; runScan(); }
function toggleIz(li,wi){ const o=ens(li,wi), w=lastScan.results[li].words[wi]; const cur=o.suffix!==undefined?o.suffix:w.suffix; o.suffix=cur==='iz'?null:'iz'; o.opt=null; runScan(); }
function toggleGraft(li,wi){ const o=ens(li,wi); o.noGraft=!o.noGraft; runScan(); }
$('scanIn').addEventListener('input',()=>{ovr={}; selWord=null; curEx=null; $('exSel').value='';});

/* ================= BAHR ================= */
function renderFams(){
  $('famList').innerHTML=FAMS.map(f=>`<div class="card" id="fam-${f.id}">
    <div class="row" style="margin-top:0"><span class="pill ${f.hindi?'':f.shape?'shape':'count'}">${f.hindi?'∿ Hindi meter':f.shape?'◆ shape':'● counting'}</span><span class="tiny faint" style="margin-left:auto">${f.gz.length} ${f.gz.length>1?'ghazals':'ghazal'} here</span></div>
    <div class="fam-name">${famLabel(f).ur}</div>
    <div class="row" style="margin:2px 0;align-items:flex-start"><span class="play" onclick="famPulsePlay('${f.id}',this)">▶︎</span><div style="flex:1;min-width:0">${f.hindi?'<div class="strip">'+strip(Scan.parseRaw(f.pattern))+'</div><p class="tiny muted" style="margin:0">feet vary line by line — tap ▶︎ on a verse to see them</p>':feetStrip(f.pattern)}</div></div>
    ${f.pair?`<p class="tiny muted">${f.pair}</p>`:''}
    ${f.gz.map((g,gi)=>{
      const disp1 = getLineDisplay(g, currentScript);
      const disp2 = g.ascii2 ? getLineDisplay({ ascii: g.ascii2, ur: g.ur2, hi: g.hi2, ro: g.ro2 }, currentScript) : '';
      const isRtl = (currentScript === 'ur');
      return `<div class="gz"><div class="top"><span class="play" onclick="famSing('${f.id}',${gi})">▶︎</span><div style="flex:1;min-width:0"><div class="who">${g.p} · ${g.ref}</div><div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:20px;direction:rtl;' : 'font-size:16px;'}">${disp1}</div>${disp2 ? `<div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:20px;direction:rtl;' : 'font-size:16px;'}margin-top:2px;">${disp2}</div>` : ''}<div class="ro tiny muted" style="margin-top:2px;">${g.ro}${g.ro2 ? ' / ' + g.ro2 : ''}</div><div id="fs-${f.id}-${gi}"></div></div></div></div>`;
    }).join('')}
  </div>`).join('');
  const all=Scan.METERS.map(m=>{
    const f=famOfMeter[m.id];
    const meta = (typeof METERS_DATA !== 'undefined' && METERS_DATA.standard) ? METERS_DATA.standard.find(x => x.id === m.id) : null;
    const metaName = meta ? `<div class="muted small" style="margin-top:2px;font-style:italic;color:var(--dim);">${meta.name} ${meta.caesura ? ' · <span class="pill count" style="font-size:10px;">Caesura //</span>' : ''}</div>` : '';
    const metaNotes = (meta && meta.notes) ? `<div class="tiny faint" style="margin-top:2px;">${meta.notes}</div>` : '';
    const famVerses = (f && f.gz) ? f.gz.map(g => {
      const disp1 = getLineDisplay(g, currentScript);
      const disp2 = g.ascii2 ? getLineDisplay({ ascii: g.ascii2, ur: g.ur2, hi: g.hi2, ro: g.ro2 }, currentScript) : '';
      const isRtl = (currentScript === 'ur');
      return `<div class="row" style="margin:4px 0;align-items:flex-start;gap:8px;">
        <span class="muted tiny" style="min-width:55px;">${g.p}:</span>
        <div style="flex:1;">
          <div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:16px;direction:rtl;' : 'font-size:13.5px;'}">${disp1}</div>
          ${disp2 ? `<div style="${isRtl ? 'font-family:\'Jameel Noori Nastaleeq\', \'Noto Nastaliq Urdu\', serif;font-size:16px;direction:rtl;' : 'font-size:13.5px;'}margin-top:2px;">${disp2}</div>` : ''}
        </div>
      </div>`;
    }).join('') : '';

    return `<div class="gz card" style="margin-bottom:8px;background:var(--bg2);">
      <div class="row" style="margin:0;justify-content:space-between;align-items:center;">
        <span class="play" onclick="playPat('${m.raw}',[...this.parentNode.querySelectorAll('.blk')])">▶︎</span>
        <div style="flex:1;min-width:0;margin:0 10px;">${feetStrip(m.raw)}</div>
        <span class="mono tiny pill count">${m.kind==='rubai'?'rubāʿī '+m.id.slice(1):'#'+m.id}</span>
      </div>
      ${metaName}
      ${metaNotes}
      ${f ? `<div style="margin-top:6px;border-top:1px solid var(--line2);padding-top:4px;">
        <div class="tiny" style="color:var(--teal);font-weight:600;">↳ Famous Verses in this Bahr:</div>
        ${famVerses}
      </div>` : ''}
    </div>`;
  }).join('');
  $('allMeters').innerHTML=all+`<div class="gz small">∿ <b class="t">Mir's Hindi meter</b> — about 15 long-beats; every even-numbered long except the 8th may become two shorts. <span class="urdu" style="font-size:14px">↳ ${famLabel(FAMS.find(f=>f.id==='ulti')).ur}</span></div>`;
}
function famPulsePlay(id,el){ const f=FAMS.find(x=>x.id===id); playPat(f.pattern,[...el.parentNode.querySelectorAll('.blk')]); }
function famSing(id,gi){ const f=FAMS.find(x=>x.id===id); singAlong(f.gz[gi].ur,f,$('fs-'+id+'-'+gi)); }

/* ================= LEARN ================= */
const WORDS=[ /* each verified with the handbook's rules */
 ['کب','kab',['l']],['کبھی','kabhī',['s','x']],['آدمی','ādmī',['l','s','x']],['اور','aur (normal)',['l','s']],
 ['ملک','mulk',['l','s']],['وقت','vaqt',['l','s']],['ورق','varaq',['s','l']],['مگر','magar',['s','l']],['غزل','ġhazal',['s','l']],
 ['ہزاروں','hazāroñ',['s','l','x']],['آہستہ','āhistah',['l','l','x']],['حیات','ḥayāt',['s','l','s']],['کتاب','kitāb',['s','l','s']],
 ['خواب','ḳhvāb (و silent)',['l','s']],['مدّت','muddat',['l','l']],['دیوار','dīvār',['l','l','s']]
];
let wdI=-1, wdIn=[];
function wdNext(){ wdI=(wdI+1)%WORDS.length; wdIn=[]; $('wdWord').textContent=WORDS[wdI][0]; $('wdRo').textContent=WORDS[wdI][1]; $('wdStrip').innerHTML=''; $('wdFb').textContent=''; }
function wdAdd(v){ if(wdIn.length<WORDS[wdI][2].length){wdIn.push(v); $('wdStrip').innerHTML=strip(wdIn);} }
function wdBack(){ wdIn.pop(); $('wdStrip').innerHTML=strip(wdIn); }
function wdCheck(){ const a=WORDS[wdI][2]; const ok=wdIn.length===a.length&&wdIn.every((v,i)=>v===a[i]);
  $('wdFb').className='fb '+(ok?'ok':'no'); $('wdFb').textContent=(ok?'✓ ':'✗ Answer: ')+a.map(x=>x==='l'?'=':x==='s'?'–':'x').join(' ');
  $('wdStrip').innerHTML=strip(a); play(a.map(x=>x==='x'?'l':x),{onStep:litter([...$('wdStrip').querySelectorAll('.blk')])}); }
const FLEX=[['جو','x'],['تو','x'],['سے','x'],['کو','x'],['کا','x'],['ہے','x'],['میں','x'],['بھی','x'],['نے','x'],['ہوں','x'],['یہ','x'],['وہ','x'],['دو','x'],['تھا','x'],
  ['تا','l'],['گو','l'],['یا','l'],['نہ','s'],['کہ','s'],['بہ','s']];
let fxI=0;
function fxNext(){ fxI=Math.floor(Math.random()*FLEX.length); $('fxWord').textContent=FLEX[fxI][0]; $('fxFb').textContent=''; }
function fxAns(v){ const a=FLEX[fxI][1], ok=v===a, L={x:'flexible',l:'always long',s:'always short'};
  $('fxFb').className='fb '+(ok?'ok':'no'); $('fxFb').textContent=(ok?'✓ ':'✗ ')+L[a]+(FLEX[fxI][0]==='تا'?' (compare تھا, which is flexible — ھ changes the word, not the count)':''); setTimeout(fxNext,1300); }
const CONSTR=[
 {t:'Word-grafting',d:'First word ends in a consonant, next begins with ا or آ: say them as one word. Optional — it happens less than half the time.',ex:[['آخر اس','ākhir is','= = =','= - =','ākhiris']]},
 {t:'Grafting, three words',d:'Ghalib runs three words together.',ex:[['کافر ان اصنام','kāfir in aṣnām','= = = = = -','= - - = = -','kāfirinaṣnām']]},
 {t:'iẓāfat on a consonant',d:'The ِ joins the last consonant into one flexible syllable.',ex:[['ملک ← ملکِ','mulk → mulk-e','= -','= x','mul-ke'],['لب ← لبِ','lab → lab-e','=','- x','la-be']]},
 {t:'iẓāfat after ā',d:'An extra syllable appears; the ā stays long.',ex:[['وفا ← وفائے','vafā → vafā-e','- =','- = x','va-fā-e']]},
 {t:'iẓāfat after ī',d:'Usually the ī turns into a consonant.',ex:[['شوخی ← شوخیِ','shoḳhī → shoḳhī-e','= x','= - x','sho-khi-ye']]},
 {t:'o, "and"',d:'After a consonant it joins it, like iẓāfat.',ex:[['دین و دل','dīn o dil','= - =','= x =','dī-no dil']]},
 {t:'al, "the"',d:'Read the word before as if it merely ended in an extra ل.',ex:[['عالم الغیب','ʿālam ul-ġhaib','= - = = -','= - = = -','ʿā-la-mul ġhai-b']]}
];
function renderConstr(){
  $('constr').innerHTML=CONSTR.map((c,ci)=>`<div class="card"><h3 style="margin:0 0 4px;font-size:18px">${c.t}</h3><p class="small muted" style="margin:0 0 6px">${c.d}</p>
   ${c.ex.map((e,ei)=>`<div class="gz"><div class="urdu" style="font-size:19px">${e[0]}</div><div class="ro">${e[1]} → ${e[4]}</div>
     <div class="row"><span class="play" onclick="cPlay(${ci},${ei},this)">▶︎</span><div class="strip">${strip(Scan.parseRaw(e[2]))}</div><span class="L">→</span><div class="strip">${strip(Scan.parseRaw(e[3]))}</div></div></div>`).join('')}</div>`).join('');
}
function cPlay(ci,ei,el){ const e=CONSTR[ci].ex[ei]; const a=sylls(Scan.parseRaw(e[2])).map(t=>t==='x'?'l':t), b=sylls(Scan.parseRaw(e[3])).map(t=>t==='x'?'s':t);
  const strips=el.parentNode.querySelectorAll('.strip'); const na=[...strips[0].querySelectorAll('.blk')], nb=[...strips[1].querySelectorAll('.blk')];
  const beat=60/settings.bpm; const d=play(a,{onStep:litter(na)}); setTimeout(()=>play(b,{onStep:litter(nb)}),(d+beat*1.5)*1000); }

/* streak + today */
const streak=store.get('streak',{n:0,last:null});
function dayKey(d){d=d||new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();}
function paintStreak(){ const done=streak.last===dayKey(); $('streakBtn').textContent=(streak.n?'🔥 ':'○ ')+streak.n+(done?' ✓':''); }
function markToday(){ const t=dayKey(); if(streak.last===t)return; const y=new Date(); y.setDate(y.getDate()-1);
  streak.n = streak.last===dayKey(y)? streak.n+1 : 1; streak.last=t; store.set('streak',streak); paintStreak(); renderToday(); }
function renderToday(){
  const done=streak.last===dayKey();
  const f=FAMS[(new Date().getDate())%FAMS.length];
  $('today').innerHTML=`<b class="t">Today, ~12 minutes</b>
    <div class="step"><span class="n">3 min</span><span>Ear → loop <span class="urdu" style="font-size:15px">${famLabel(f).ur}</span> and sing along to both misras.</span></div>
    <div class="step"><span class="n">4 min</span><span>Tap → five echoes. Aim for "perfect" three times.</span></div>
    <div class="step"><span class="n">5 min</span><span>Scan → one sher from a ghazal you love. Stack both misras; confirm the bahr.</span></div>
    <div class="row"><button class="btn ${done?'':'gold'} sm" onclick="markToday()">${done?'✓ Done today':'Mark today done'}</button></div>`;
}

